                    brazilPrice: 32,
                    colombiaPrice: 20,
                    euEtsPrice: 65,
                    reddPrice: 3,
                    biogasPrice: 17,
                    cookstovePrice: 24,
                    freeAllowances: 660,
                    complianceObligation: 992,
                    strategic: null,
                    briefingEn: '<b>2030: SBTi Milestone Assessment</b><br><br>This is the SBTi interim milestone year. Your performance across 6 years will be assessed against the 42% reduction target (812,580 tCO2e or less).<br><br>Brazil allowance price has reached <b>$32/tonne</b>. UK CBAM is now enacted. US Carbon Tariff legislation is in Senate.<br><br>Final measure unlocked: Direct Air Capture ($28M, 15,000 tCO2e, $210/tonne). The 2040 net-zero pathway begins here.',
                    briefingEs: '<b>2030: Evaluación del Hito SBTi</b><br><br>Este es el año del hito intermedio SBTi. Tu desempeño a lo largo de 6 años será evaluado contra la meta de reducción del 42% (812,580 tCO2e o menos).<br><br>El precio de permisos de Brasil ha alcanzado <b>$32/tonelada</b>. El CBAM del Reino Unido está ahora promulgado. La legislación de Tarifa de Carbono de EEUU está en el Senado.<br><br>Última medida desbloqueada: Captura Directa de Aire ($28M, 15,000 tCO2e, $210/tonelada). El camino a cero neto 2040 comienza aquí.'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    emissions: 1310000,
                    baselineEmissions: 1401000,
                    sbtiTarget: 812580,
                    totalCarbonCost: 0,
                    implementedMeasures: [],
                    totalAbatementReduction: 0,
                    maxPossibleAbatement: 421000,
                    trajectoryScore: 50,
                    creditQualityScore: 75,
                    complianceStatus: 'green',
                    totalReddCredits: 0,
                    totalBiogasCredits: 0,
                    totalCookstoveCredits: 0,
                    totalAllowancesBanked: 0,
                    icpLevel: 0,
                    cbamStrategy: 0,
                    cbamTotalPaid: 0,
                    controversyResponse: 0,
                    emissionsHistory: [],
                    costHistory: [],
                    trajectoryHistory: [],
                    qualityHistory: [],
                    abatementPctHistory: [],
                    compliancePenaltyTotal: 0,
                    firstCbamCost: 0
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    abatementBudget: 0,
                    allowancePurchase: 0,
                    offsetRedd: 0,
                    offsetBiogas: 0,
                    offsetCookstove: 0,
                    strategicChoice: 0
                };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var lang = (window.mySimulation && (window.mySimulation.lang || window.mySimulation.currentLanguage)) || 'en';

            var yearEl = document.getElementById('yearDisplay');
            if (yearEl) yearEl.textContent = '(' + round.year + ')';

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = lang === 'es' ? round.briefingEs : round.briefingEn;
            }

            var priceEl = document.getElementById('pricePanel');
            if (priceEl) {
                var priceHtml = lang === 'es'
                    ? '<b>Precios de Carbono:</b> Brasil SBCE: $' + round.brazilPrice + '/t'
                    : '<b>Carbon Prices:</b> Brazil SBCE: $' + round.brazilPrice + '/t';
                priceHtml += ' | Colombia Tax: $' + round.colombiaPrice + '/t';
                if (round.euEtsPrice > 0) {
                    priceHtml += ' | EU ETS (CBAM): $' + round.euEtsPrice + '/t';
                }
                priceHtml += '<br>';
                priceHtml += lang === 'es'
                    ? '<b>Créditos Voluntarios:</b> '
                    : '<b>Voluntary Credits:</b> ';
                priceHtml += 'REDD+: $' + round.reddPrice + '/t | ';
                priceHtml += lang === 'es' ? 'Biogas: $' : 'Biogas: $';
                priceHtml += round.biogasPrice + '/t | ';
                priceHtml += lang === 'es' ? 'Estufas: $' : 'Cookstove: $';
                priceHtml += round.cookstovePrice + '/t';
                priceHtml += '<br>';
                priceHtml += lang === 'es'
                    ? '<b>Presupuesto del Año:</b> $' + round.budget + 'M'
                    : '<b>Year Budget:</b> $' + round.budget + 'M';
                priceEl.innerHTML = priceHtml;
            }

            var allowHint = document.getElementById('allowancePriceText');
            if (allowHint) {
                allowHint.textContent = lang === 'es'
                    ? 'Precio actual: $' + round.brazilPrice + '/tCO2e'
                    : 'Current price: $' + round.brazilPrice + '/tCO2e';
            }

            var ds = state.domainState || {};
            var implemented = ds.implementedMeasures || [];
            var currentPeriod = state.currentPeriod || 1;
            var available = [];
            for (var m = 0; m < this.MEASURES.length; m++) {
                if (this.MEASURES[m].round <= currentPeriod && implemented.indexOf(m) === -1) {
                    available.push(this.MEASURES[m].name + ' ($' + this.MEASURES[m].cost + 'M)');
                }
            }
            var measHint = document.getElementById('availableMeasuresText');
            if (measHint) {
                measHint.innerHTML = lang === 'es'
                    ? 'Medidas disponibles: ' + (available.length > 0 ? available.join(', ') : 'Ninguna')
                    : 'Available measures: ' + (available.length > 0 ? available.join(', ') : 'None');
            }

            var stratPanel = document.getElementById('strategicPanel');
            var stratSelect = document.getElementById('strategicSelect');
            var stratLabel = document.getElementById('strategicLabel');
            if (stratPanel && stratSelect) {
                if (round.strategic === 'cbam') {
                    stratPanel.style.display = 'block';
                    if (stratLabel) stratLabel.textContent = lang === 'es' ? 'Estrategia CBAM' : 'CBAM Strategy';
                    stratSelect.innerHTML = '<option value="1">' + (lang === 'es' ? 'Absorber costo CBAM' : 'Absorb CBAM cost') + '</option>'
                        + '<option value="2">' + (lang === 'es' ? 'Trasladar a compradores UE' : 'Pass through to EU buyers') + '</option>'
                        + '<option value="3">' + (lang === 'es' ? 'Invertir en reducción de emisiones' : 'Invest in emissions reduction') + '</option>'
                        + '<option value="4">' + (lang === 'es' ? 'Redirigir exportaciones fuera de UE' : 'Redirect exports away from EU') + '</option>';
                } else if (round.strategic === 'icp') {
                    stratPanel.style.display = 'block';
                    if (stratLabel) stratLabel.textContent = lang === 'es' ? 'Nivel de Precio Interno de Carbono' : 'Internal Carbon Price Level';
                    stratSelect.innerHTML = '<option value="20">$20/tCO2e (' + (lang === 'es' ? 'Precio Sombra' : 'Shadow Price') + ')</option>'
                        + '<option value="40">$40/tCO2e (' + (lang === 'es' ? 'Precio Sombra' : 'Shadow Price') + ')</option>'
                        + '<option value="70">$70/tCO2e (' + (lang === 'es' ? 'Tasa y Dividendo' : 'Fee-and-Dividend') + ')</option>'
                        + '<option value="100">$100/tCO2e (' + (lang === 'es' ? 'Tasa y Dividendo' : 'Fee-and-Dividend') + ')</option>';
                } else if (round.strategic === 'controversy') {
                    stratPanel.style.display = 'block';
                    if (stratLabel) stratLabel.textContent = lang === 'es' ? 'Respuesta a Controversia REDD+' : 'REDD+ Controversy Response';
                    stratSelect.innerHTML = '<option value="1">' + (lang === 'es' ? 'Mantener y defender créditos REDD+' : 'Hold and defend REDD+ credits') + '</option>'
                        + '<option value="2">' + (lang === 'es' ? 'Reemplazo parcial (50% a biogas)' : 'Partial replacement (50% to biogas)') + '</option>'
                        + '<option value="3">' + (lang === 'es' ? 'Reemplazo total (todo a biogas/estufas)' : 'Full replacement (all to biogas/cookstove)') + '</option>';
                } else {
                    stratPanel.style.display = 'none';
                }
            }
        }

        validateDecisions(decisions) {
            var abIn = document.getElementById('abatementBudgetInput');
            if (abIn) decisions.abatementBudget = parseFloat(abIn.value) || 0;

            var alIn = document.getElementById('allowanceInput');
            if (alIn) decisions.allowancePurchase = parseFloat(alIn.value) || 0;

            var rdIn = document.getElementById('reddInput');
            if (rdIn) decisions.offsetRedd = parseFloat(rdIn.value) || 0;

            var bgIn = document.getElementById('biogasInput');
            if (bgIn) decisions.offsetBiogas = parseFloat(bgIn.value) || 0;

            var csIn = document.getElementById('cookstoveInput');
            if (csIn) decisions.offsetCookstove = parseFloat(csIn.value) || 0;

            var stIn = document.getElementById('strategicSelect');
            if (stIn) decisions.strategicChoice = parseFloat(stIn.value) || 0;

            this._updateBriefing(window.mySimulation.state);

            var idx = Math.min((window.mySimulation.state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var allowanceCost = (decisions.allowancePurchase * round.brazilPrice) / 1000;
            var offsetCost = (decisions.offsetRedd * round.reddPrice + decisions.offsetBiogas * round.biogasPrice + decisions.offsetCookstove * round.cookstovePrice) / 1000;
            var totalSpend = decisions.abatementBudget + allowanceCost + offsetCost;

            if (totalSpend > round.budget * 1.05) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_warning'), 'warning'
                );
                return false;
            }

            if (decisions.abatementBudget < 0 || decisions.allowancePurchase < 0 || decisions.offsetRedd < 0 || decisions.offsetBiogas < 0 || decisions.offsetCookstove < 0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('negative_warning'), 'warning'
                );
                return false;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var newMeasures = [];
            var abatementSpent = 0;
            var newReduction = 0;
            var budget = d.abatementBudget;

            var available = [];
            for (var m = 0; m < this.MEASURES.length; m++) {
                if (this.MEASURES[m].round <= state.currentPeriod && ds.implementedMeasures.indexOf(m) === -1) {
                    available.push({ idx: m, measure: this.MEASURES[m] });
                }
            }
            available.sort(function(a, b) { return a.measure.cpt - b.measure.cpt; });

            for (var i = 0; i < available.length; i++) {
                var meas = available[i];
                if (abatementSpent + meas.measure.cost <= budget + 0.01) {
                    abatementSpent += meas.measure.cost;
                    newReduction += meas.measure.reduction;
                    newMeasures.push(meas.idx);
                    ds.implementedMeasures.push(meas.idx);
                }
            }

            ds.totalAbatementReduction += newReduction;
            ds.emissions = Math.max(0, ds.emissions - newReduction);

            var allowanceCost = (d.allowancePurchase * round.brazilPrice) / 1000;
            ds.totalAllowancesBanked += d.allowancePurchase;

            var reddCost = (d.offsetRedd * round.reddPrice) / 1000;
            var biogasCost = (d.offsetBiogas * round.biogasPrice) / 1000;
            var cookstoveCost = (d.offsetCookstove * round.cookstovePrice) / 1000;
            var offsetCost = reddCost + biogasCost + cookstoveCost;

            ds.totalReddCredits += d.offsetRedd;
            ds.totalBiogasCredits += d.offsetBiogas;
            ds.totalCookstoveCredits += d.offsetCookstove;

            var totalOffsetCredits = d.offsetRedd + d.offsetBiogas + d.offsetCookstove;

            var complianceDeficit = Math.max(0, ds.emissions / 1000 - round.freeAllowances / 1000);
            var complianceCostExtra = 0;
            if (d.allowancePurchase < complianceDeficit * 0.8) {
                ds.complianceStatus = 'amber';
                complianceCostExtra = (complianceDeficit - d.allowancePurchase) * round.brazilPrice * 1.5 / 1000;
            } else {
                ds.complianceStatus = 'green';
            }

            var cbamCost = 0;
            if (round.euEtsPrice > 0) {
                var emissionsIntensity = 1.82;
                if (ds.implementedMeasures.indexOf(5) !== -1) emissionsIntensity -= 0.3;
                if (ds.implementedMeasures.indexOf(8) !== -1) emissionsIntensity -= 0.35;
                var cbamPerTonne = Math.max(0, (round.euEtsPrice - round.brazilPrice) * emissionsIntensity);

                var exportVolume = 120000;
                if (ds.cbamStrategy === 4) exportVolume = 60000;

                cbamCost = (cbamPerTonne * exportVolume) / 1000000;
                ds.cbamTotalPaid += cbamCost;
            }

            var colombiaTax = (round.colombiaPrice * 89000 + round.colombiaPrice * 178000 * 0.3 + round.colombiaPrice * 142000 * 0.5) / 1000000;

            var totalRoundCost = abatementSpent + allowanceCost + offsetCost + cbamCost + colombiaTax + complianceCostExtra;
            ds.totalCarbonCost += totalRoundCost;

            if (round.strategic === 'cbam') ds.cbamStrategy = d.strategicChoice;
            if (round.strategic === 'icp') ds.icpLevel = d.strategicChoice;
            if (round.strategic === 'controversy') ds.controversyResponse = d.strategicChoice;

            var icpBonus = 0;
            if (ds.icpLevel >= 70) icpBonus = 15000;
            else if (ds.icpLevel >= 40) icpBonus = 8000;
            else if (ds.icpLevel >= 20) icpBonus = 3000;
            ds.emissions = Math.max(0, ds.emissions - icpBonus);
            ds.totalAbatementReduction += icpBonus;

            var targetPath = ds.baselineEmissions - ((ds.baselineEmissions - ds.sbtiTarget) * (state.currentPeriod / 6));
            var deviation = (ds.emissions - targetPath) / ds.baselineEmissions;
            var offsetBoost = Math.min(20, totalOffsetCredits * 1000 / ds.baselineEmissions * 100);
            ds.trajectoryScore = Math.max(0, Math.min(100, Math.round(80 - deviation * 500 + offsetBoost)));

            var totalCredits = ds.totalReddCredits + ds.totalBiogasCredits + ds.totalCookstoveCredits;
            if (totalCredits > 0) {
                var reddWeight = ds.totalReddCredits / totalCredits;
                var biogasWeight = ds.totalBiogasCredits / totalCredits;
                var cookstoveWeight = ds.totalCookstoveCredits / totalCredits;

                var reddQuality = 45;
                if (state.currentPeriod >= 4 && ds.controversyResponse !== 3) reddQuality = 25;
                if (state.currentPeriod >= 4 && ds.controversyResponse === 2) reddQuality = 35;

                ds.creditQualityScore = Math.round(reddWeight * reddQuality + biogasWeight * 88 + cookstoveWeight * 95);
            } else {
                ds.creditQualityScore = 75;
            }

            var abatementPct = Math.round((ds.totalAbatementReduction / ds.maxPossibleAbatement) * 100);

            ds.emissionsHistory.push(ds.emissions);
            ds.costHistory.push(Math.round(totalRoundCost * 10) / 10);
            ds.trajectoryHistory.push(ds.trajectoryScore);
            ds.qualityHistory.push(ds.creditQualityScore);
            ds.abatementPctHistory.push(abatementPct);

            if (ds.complianceStatus === 'amber') ds.compliancePenaltyTotal += 1;
            if (ds.complianceStatus === 'red') ds.compliancePenaltyTotal += 3;
            if (state.currentPeriod === 2) ds.firstCbamCost = cbamCost;
            var cbamBonusNow = (state.currentPeriod >= 5 && ds.firstCbamCost > 0 && cbamCost < ds.firstCbamCost * 0.6) ? 5 : 0;
            // platform score: same composite getPerformanceSummary uses for its final verdict, read from the running domainState accumulators instead of re-scanning history
            var overallScore = Math.max(0, Math.min(100, Math.round(
                ds.trajectoryScore * 0.35 +
                abatementPct * 0.25 +
                Math.max(0, 100 - ds.totalCarbonCost * 0.8) * 0.20 +
                ds.creditQualityScore * 0.15 +
                Math.max(0, (100 - ds.compliancePenaltyTotal * 10)) * 0.05 +
                cbamBonusNow
            )));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            // Advance the year briefing/prices/strategic panel synchronously. state.currentPeriod
            // is still the year we just scored (the framework increments it *after* this method
            // returns), so the next year is currentPeriod + 1. The prior 500ms timer fired *after*
            // that increment, reading currentPeriod+1 and adding 1 again — showing year N+2 and
            // skipping N+1. That mis-timed the year-specific STRATEGIC decision (CBAM/ICP/
            // controversy), so e.g. an ICP value was written into cbamStrategy.
            this._updateBriefing({ currentPeriod: state.currentPeriod + 1, domainState: ds });

            return {
                period: state.currentPeriod,
                year: round.year,
                emissions: ds.emissions,
                newReduction: newReduction,
                abatementSpent: Math.round(abatementSpent * 10) / 10,
                allowanceCost: Math.round(allowanceCost * 10) / 10,
                offsetCost: Math.round(offsetCost * 10) / 10,
                cbamCost: Math.round(cbamCost * 10) / 10,
                totalRoundCost: Math.round(totalRoundCost * 10) / 10,
                trajectoryScore: ds.trajectoryScore,
                creditQuality: ds.creditQualityScore,
                abatementPct: abatementPct,
                compliance: ds.complianceStatus
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('emissionsDisplay', 'domainState.emissions',
