            uiManager.bind('trajectoryDisplay', 'domainState.trajectoryScore');
            uiManager.bind('qualityDisplay', 'domainState.creditQualityScore',
                function(v) { return v + '/100'; });
            uiManager.bind('abatementDisplay', 'domainState.totalAbatementReduction',
