        getChartData(state) {
            var labels = state.domainState.emissionsHistory.map(function(_, i) {
                return String(2025 + i);
            });
            var baseline = state.domainState.baselineEmissions;
            var target = state.domainState.sbtiTarget;
            var targetPath = labels.map(function(_, i) {
                return Math.round(baseline - ((baseline - target) * ((i + 1) / 6)));
            });
            return {
                emissionsChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.emissionsHistory },
                        { data: targetPath }
                    ]
                },
                costChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.costHistory }]
                }
            };
