    document.addEventListener('DOMContentLoaded', function() {
        var adapter = new CarbonTradingAdapter();
        window.mySimulation = new USF.SimulationFramework();
        // Re-sync the year briefing/strategic panel after UNDO: the host player's undo()
        // rewinds domainState + the counter but never re-renders sim-owned content.
        var undoBtn = document.getElementById('undoBtn');
        if (undoBtn) undoBtn.addEventListener('click', function () {
            setTimeout(function () { try { adapter._updateBriefing(window.mySimulation.state); } catch (e) {} }, 0);
        });
        window.mySimulation.initialize(adapter, {
            simulationType: 'carbon_trading_climate_finance',
            maxPeriods: 6,
            autoSaveInterval: 30000
        });
    });

})();
